export default function Gallery({
  themeMode,
  onThemeMode,
}: {
  themeMode: ThemeMode;
  onThemeMode: (mode: ThemeMode) => void;
}) {
  const themes: readonly { id: ResolvedTheme; label: string }[] = [
    { id: "light", label: ja.gallery.themeLight },
    { id: "dark", label: ja.gallery.themeDark },
  ];

  // Open fixtures (menu popover) call scrollIntoView when Fluent autofocuses
  // the first item on mount; pin the gallery scroll to the top so the page
  // always opens at the light-theme section. The rAF covers any deferred
  // scroll scheduled after this effect runs.
  useEffect(() => {
    const pin = () => {
      const root = document.querySelector<HTMLElement>(".hs-gallery");
      if (root) root.scrollTop = 0;
      document.documentElement.scrollTop = 0;
      document.body.scrollTop = 0;
    };
    pin();
    const raf = requestAnimationFrame(pin);
    return () => cancelAnimationFrame(raf);
  }, []);

  return (
    <div className="hs-gallery" role="main" aria-label={ja.gallery.title}>
      <header className="hs-gallery__header">
        <h1 className="hs-gallery__title">{ja.gallery.title}</h1>
        <StatusBadge tone="info" label={ja.gallery.devBadge} />
        <span className="hs-gallery__spacer" />
        <SegmentedControl
          options={THEME_OPTIONS}
          value={themeMode}
          onChange={onThemeMode}
          ariaLabel={ja.settings.themeLabel}
        />
        <HsButton
          variant="subtle"
          onClick={() => {
            window.location.hash = "";
          }}
        >
          {ja.common.back}
        </HsButton>
        <p className="hs-gallery__note">{ja.gallery.note}</p>
      </header>

      {themes.map((t) => (
        <section key={t.id} data-hs-theme={t.id} className="hs-gallery__theme">
          <FluentProvider
            theme={t.id === "dark" ? hsDarkTheme : hsLightTheme}
            style={{ display: "contents" }}
          >
            <h2 className="hs-gallery__theme-title">{t.label}</h2>
            <PrimitiveSections />
          </FluentProvider>
        </section>
      ))}
    </div>
  );
}

/**
 * SidecarClient ↔ MockSidecarPort tests (UI-040).
 *
 * The mock speaks the real NDJSON contract, so these tests exercise the
 * same supervision semantics the UI-002 harness proved against
 * `python -m hornscribe.worker`: handshake/capabilities, id correlation,
 * progress streaming, cooperative cancel, crash detection, watchdog
 * unresponsiveness, graceful shutdown, malformed-frame containment.
 */

import { describe, expect, it } from "vitest";
import { SidecarClient, type SidecarClientState } from "./client";
import { MockSidecarPort } from "./mockPort";
import {
  ERR,
  PROTOCOL_VERSION,
  type JobEventPayload,
} from "./protocol";
import { UnsupportedSidecarPort } from "./port";

function connect(opts: ConstructorParameters<typeof SidecarClient>[1] = {}) {
  const port = new MockSidecarPort();
  const client = new SidecarClient(port, {
    requestTimeoutMs: 250,
    handshakeTimeoutMs: 500,
    watchdogMs: 40,
    pingTimeoutMs: 30,
    ...opts,
  });
  const events: JobEventPayload[] = [];
  const states: SidecarClientState[] = [];
  const diags: string[] = [];
  client.onJobEvent((e) => events.push(e));
  client.onStateChange((s) => states.push(s));
  client.onDiagnostic((l) => diags.push(l));
  return { port, client, events, states, diags };
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function until(cond: () => boolean, ms = 1000): Promise<void> {
  const deadline = Date.now() + ms;
  while (!cond()) {
    if (Date.now() > deadline) throw new Error("timed out waiting for condition");
    await sleep(2);
  }
}

describe("handshake + lifecycle", () => {
  it("handshakes and reports protocol version, engine info, capabilities", async () => {
    const { client } = connect();
    const hs = await client.start();
    expect(client.getState()).toBe("ready");
    expect(hs.protocolVersion).toBe(PROTOCOL_VERSION);
    expect(hs.engineInfo.name).toBe("hornscribe-engine");
    expect(hs.capabilities.cooperativeCancel).toBe(true);
    expect(hs.capabilities.cancellationFallback).toBe("terminate+restart");
    expect(hs.capabilities.jobKinds).toContain("transcription");
    await client.shutdown();
    expect(client.getState()).toBe("closed");
  });

  it("refuses an incompatible protocol version and the worker exits", async () => {
    const port = new MockSidecarPort();
    await port.start();
    const seen: string[] = [];
    port.onLine((l) => seen.push(l));
    const exited = new Promise<number | null>((r) => port.onExit(r));
    port.writeLine(
      JSON.stringify({
        v: 1,
        id: "req-1",
        kind: "request",
        method: "engine.handshake",
        payload: { protocolVersion: 99 },
        error: null,
      }),
    );
    await until(() => seen.length > 0);
    const resp = JSON.parse(seen[0]);
    expect(resp.error.code).toBe(ERR.PROTOCOL_VERSION_MISMATCH);
    expect(resp.error.details.supported).toEqual([1]);
    expect(await exited).toBe(0); // refusal, not a crash
  });

  it("ping echoes and correlates ids while a job streams events", async () => {
    const { client, events } = connect();
    await client.start();
    await client.startJob("demoLongTask", { steps: 30, stepDurationMs: 5 });
    const pong = await client.ping("hello-42");
    expect(pong.echo).toBe("hello-42");
    expect(pong.workerPid).toBe(4242);
    // Events interleaved with the ping did not disturb correlation.
    expect(events.length).toBeGreaterThan(0);
    await client.shutdown();
  });

  it("requests issued before ready fail with ENGINE_NOT_READY", async () => {
    const { client } = connect();
    await expect(client.ping()).rejects.toMatchObject({
      code: ERR.ENGINE_NOT_READY,
    });
  });
});

describe("job lifecycle", () => {
  it("streams started → progress → completed with a real fraction", async () => {
    const { client, events } = connect();
    await client.start();
    const res = await client.startJob("demoLongTask", {
      steps: 3,
      stepDurationMs: 1,
    });
    expect(res.state).toBe("accepted");
    await until(
      () => events.some((e) => e.phase === "completed"),
    );
    const phases = events.map((e) => e.phase);
    expect(phases[0]).toBe("started");
    expect(phases[phases.length - 1]).toBe("completed");
    // Exactly one terminal event; progress is monotonic and real.
    expect(
      events.filter((e) =>
        ["completed", "cancelled", "failed"].includes(e.phase),
      ),
    ).toHaveLength(1);
    const progresses = events
      .filter((e) => typeof e.progress === "number")
      .map((e) => e.progress as number);
    for (let i = 1; i < progresses.length; i++) {
      expect(progresses[i]).toBeGreaterThanOrEqual(progresses[i - 1]);
    }
    expect(client.inFlightJobs).toHaveLength(0);
    await client.shutdown();
  });

  it("transcription jobs carry stage fields in pipeline order", async () => {
    const { client, events } = connect();
    await client.start();
    await client.startJob("transcription", { steps: 7, stepDurationMs: 1 });
    await until(() => events.some((e) => e.phase === "completed"));
    const stages = events
      .map((e) => e.stage)
      .filter((s): s is string => typeof s === "string");
    expect(stages[0]).toBe("preparing_audio");
    expect(stages).toContain("rendering");
    const done = events.find((e) => e.phase === "completed");
    expect(done?.result).toMatchObject({
      reviewIssues: expect.arrayContaining([
        expect.objectContaining({ reason: "quantization_ambiguous" }),
      ]),
    });
    await client.shutdown();
  });

  it("job.cancel ends the job in a terminal cancelled event", async () => {
    const { client, events } = connect();
    await client.start();
    const res = await client.startJob("demoLongTask", {
      steps: 50,
      stepDurationMs: 5,
    });
    const ack = await client.cancelJob(res.jobId);
    expect(ack.cancellation).toBe("requested");
    await until(() => events.some((e) => e.phase === "cancelled"));
    // Deterministic terminal state: cancelled, exactly once.
    expect(events.filter((e) => e.phase === "cancelled")).toHaveLength(1);
    expect(client.inFlightJobs).toHaveLength(0);
    await client.shutdown();
  });

  it("cancel of a finished/unknown job reports JOB_NOT_FOUND", async () => {
    const { client } = connect();
    await client.start();
    await expect(client.cancelJob("job-9999")).rejects.toMatchObject({
      code: ERR.JOB_NOT_FOUND,
    });
    await client.shutdown();
  });

  it("a second concurrent job is rejected JOB_ALREADY_RUNNING", async () => {
    const { client } = connect();
    await client.start();
    await client.startJob("demoLongTask", { steps: 20, stepDurationMs: 10 });
    await expect(
      client.startJob("demoLongTask", { steps: 1, stepDurationMs: 1 }),
    ).rejects.toMatchObject({ code: ERR.JOB_ALREADY_RUNNING });
    await client.shutdown();
  });

  it("deadlineMs ends the job in failed/JOB_TIMEOUT", async () => {
    const { client, events } = connect();
    await client.start();
    await client.startJob("demoLongTask", {
      steps: 50,
      stepDurationMs: 15,
      deadlineMs: 10,
    });
    await until(() => events.some((e) => e.phase === "failed"));
    const failed = events.find((e) => e.phase === "failed");
    expect(failed?.error?.code).toBe(ERR.JOB_TIMEOUT);
    await client.shutdown();
  });
});

describe("crash + supervision", () => {
  it("a mid-job crash marks the client crashed and kills pending work", async () => {
    const { port, client, events, states } = connect();
    await client.start();
    await client.startJob("demoLongTask", { steps: 100, stepDurationMs: 10 });
    await until(() => events.some((e) => e.phase === "progress"));
    // Wedge the worker so a request stays genuinely in flight, then crash.
    port.simulateHang();
    const pending = client.ping();
    port.simulateCrash();
    await expect(pending).rejects.toMatchObject({
      code: ERR.WORKER_CRASHED,
    });
    await until(() => client.getState() === "crashed");
    expect(states).toContain("crashed");
    // ADR-0002: the in-flight job got NO terminal event from the worker —
    // marking it failed is the session's job (tested in session.test.ts).
    expect(events.some((e) => e.phase === "completed")).toBe(false);
    expect(events.some((e) => e.phase === "cancelled")).toBe(false);
  });

  it("watchdog catches a wedged worker while a job is in flight", async () => {
    const { port, client, events } = connect({ watchdogMs: 40, pingTimeoutMs: 30 });
    await client.start();
    await client.startJob("demoLongTask", { steps: 100, stepDurationMs: 10 });
    await until(() => events.some((e) => e.phase === "progress"));
    port.simulateHang(); // like debug.hang — loop wedges, silence follows
    await until(() => client.getState() === "unresponsive", 2000);
  });

  it("watchdog stays quiet while progress keeps flowing", async () => {
    const { client, events } = connect({ watchdogMs: 60 });
    await client.start();
    await client.startJob("demoLongTask", { steps: 4, stepDurationMs: 10 });
    await until(() => events.some((e) => e.phase === "completed"));
    expect(client.getState()).toBe("ready");
    await client.shutdown();
  });

  it("a request that outlives its timeout rejects REQUEST_TIMEOUT", async () => {
    const { port, client } = connect();
    await client.start();
    port.simulateHang();
    await expect(client.ping()).rejects.toMatchObject({
      code: ERR.REQUEST_TIMEOUT,
    });
  });

  it("UnsupportedSidecarPort fails explicitly — the packaged-app gate", async () => {
    const client = new SidecarClient(new UnsupportedSidecarPort());
    await expect(client.start()).rejects.toMatchObject({
      code: ERR.ENGINE_UNAVAILABLE,
    });
    expect(client.getState()).toBe("crashed");
  });
});

describe("malformed-frame containment (worker contract)", () => {
  it("garbage JSON gets MALFORMED_MESSAGE with null id; worker stays up", async () => {
    const port = new MockSidecarPort();
    await port.start();
    const seen: string[] = [];
    port.onLine((l) => seen.push(l));
    port.writeLine("this is not json{");
    port.writeLine(JSON.stringify({ hello: "world" }));
    await until(() => seen.length >= 2);
    const a = JSON.parse(seen[0]);
    const b = JSON.parse(seen[1]);
    expect(a.error.code).toBe(ERR.MALFORMED_MESSAGE);
    expect(a.id).toBeNull();
    expect(b.error.code).toBe(ERR.MALFORMED_MESSAGE);
    // Still alive and answering.
    port.writeLine(
      JSON.stringify({
        v: 1,
        id: "req-ok",
        kind: "request",
        method: "engine.ping",
        payload: { echo: "still-here" },
        error: null,
      }),
    );
    await until(() => seen.length >= 3);
    expect(JSON.parse(seen[2]).payload.echo).toBe("still-here");
  });

  it("inbound event/response frames to the worker are dropped, not answered", async () => {
    const port = new MockSidecarPort();
    await port.start();
    const seen: string[] = [];
    const errs: string[] = [];
    port.onLine((l) => seen.push(l));
    port.onStderr((l) => errs.push(l));
    port.writeLine(
      JSON.stringify({
        v: 1,
        id: null,
        kind: "event",
        method: "job.event",
        payload: {},
        error: null,
      }),
    );
    await sleep(10);
    expect(seen).toHaveLength(0); // never answered → no reply loop
    expect(errs.some((l) => l.includes("ignoring inbound"))).toBe(true);
  });

  it("client routes the null-id error response to diagnostics, not a request", async () => {
    const { port, client, diags } = connect();
    await client.start();
    // Garbage INTO the port → mock answers MALFORMED_MESSAGE with id:null
    // (the one sanctioned null-id response) → client logs it as a
    // diagnostic instead of resolving any request.
    port.writeLine("garbage{{{");
    await until(() => diags.some((l) => l.includes("null-id error response")));
    const pong = await client.ping("ok");
    expect(pong.echo).toBe("ok");
  });
});

/**
 * SidecarClient — typed NDJSON protocol client over a {@link SidecarPort}.
 *
 * Implements the shell half of protocol/PROTOCOL.md:
 *
 * - `engine.handshake` on {@link start} (first message after spawn);
 *   a protocol-version mismatch fails explicitly — the worker exits and
 *   the client surfaces the refusal.
 * - request/response correlation by id; events (`job.event`) are demuxed
 *   to subscribers and never disturb pending requests.
 * - per-request timeouts → `SidecarError(REQUEST_TIMEOUT)`.
 * - an in-flight-job watchdog: while any job is active, silence longer
 *   than `watchdogMs` triggers an `engine.ping` probe; a probe timeout
 *   marks the client `unresponsive` (worker.py `debug.hang` proved this
 *   supervision path engine-side).
 * - crash detection: a port exit that was not a requested shutdown marks
 *   the client `crashed`, rejects pending requests with WORKER_CRASHED and
 *   notifies subscribers — the session layer then marks the in-flight job
 *   failed (ADR-0002: never silently resubmitted).
 *
 * Malformed inbound lines are routed to the diagnostics channel and
 * dropped — never answered — mirroring the worker's own containment rule.
 */

import {
  ERR,
  PROTOCOL_VERSION,
  SidecarError,
  encodeFrame,
  isTerminalPhase,
  parseInboundFrame,
  requestFrame,
  type EngineCapabilities,
  type EngineInfo,
  type HandshakeResult,
  type JobCancelResult,
  type JobEventPayload,
  type JobStartResult,
  type PingResult,
  type ProtocolErrorObject,
  type ShutdownResult,
} from "./protocol";
import type { SidecarPort } from "./port";

export type SidecarClientState =
  /** Constructed, not yet started. */
  | "idle"
  /** port.start + handshake in flight. */
  | "starting"
  /** Handshake done — requests may be issued. */
  | "ready"
  /** Graceful shutdown completed (or exit after close). */
  | "closed"
  /** Worker exited without a requested shutdown. */
  | "crashed"
  /** Watchdog probe timed out while a job was in flight. */
  | "unresponsive";

export interface SidecarClientOptions {
  /** Default per-request timeout. */
  requestTimeoutMs?: number;
  /** Handshake timeout — interpreter cold start can be slow (UI-002
   *  measured ≈200 ms locally; packaged first-run may be far slower). */
  handshakeTimeoutMs?: number;
  /** Silence tolerated while a job is in flight before probing. */
  watchdogMs?: number;
  /** Probe (`engine.ping`) timeout once the watchdog fires. */
  pingTimeoutMs?: number;
}

interface PendingRequest {
  method: string;
  resolve: (payload: unknown) => void;
  reject: (err: SidecarError) => void;
  timer: ReturnType<typeof setTimeout>;
}

const DEFAULTS: Required<SidecarClientOptions> = {
  requestTimeoutMs: 10_000,
  handshakeTimeoutMs: 30_000,
  watchdogMs: 15_000,
  pingTimeoutMs: 5_000,
};

export class SidecarClient {
  private readonly port: SidecarPort;
  private readonly opts: Required<SidecarClientOptions>;
  private state: SidecarClientState = "idle";
  private counter = 0;
  private readonly pending = new Map<string, PendingRequest>();
  private readonly jobEventCbs = new Set<(e: JobEventPayload) => void>();
  private readonly stateCbs = new Set<(s: SidecarClientState) => void>();
  private readonly diagCbs = new Set<(line: string) => void>();
  private readonly activeJobs = new Set<string>();
  private watchdogTimer: ReturnType<typeof setTimeout> | null = null;
  private probing = false;
  private shutdownRequested = false;
  private handshakeResult: HandshakeResult | null = null;

  constructor(port: SidecarPort, opts: SidecarClientOptions = {}) {
    this.port = port;
    this.opts = { ...DEFAULTS, ...opts };
    port.onLine((line) => this.handleLine(line));
    port.onStderr((line) => this.diagnose(`stderr: ${line}`));
    port.onExit((code) => this.handleExit(code));
  }

  // ---- surface ---------------------------------------------------------

  getState(): SidecarClientState {
    return this.state;
  }

  get engineInfo(): EngineInfo | null {
    return this.handshakeResult?.engineInfo ?? null;
  }

  get capabilities(): EngineCapabilities | null {
    return this.handshakeResult?.capabilities ?? null;
  }

  get handshake(): HandshakeResult | null {
    return this.handshakeResult;
  }

  /** Ids of jobs started via this client that have not reached a
   *  terminal event (used by the session for crash bookkeeping). */
  get inFlightJobs(): readonly string[] {
    return [...this.activeJobs];
  }

  onJobEvent(cb: (e: JobEventPayload) => void): () => void {
    this.jobEventCbs.add(cb);
    return () => this.jobEventCbs.delete(cb);
  }

  onStateChange(cb: (s: SidecarClientState) => void): () => void {
    this.stateCbs.add(cb);
    return () => this.stateCbs.delete(cb);
  }

  /** Diagnostics channel: malformed inbound frames, stderr lines,
   *  supervision notes. Never user-facing copy. */
  onDiagnostic(cb: (line: string) => void): () => void {
    this.diagCbs.add(cb);
    return () => this.diagCbs.delete(cb);
  }

  private setState(s: SidecarClientState): void {
    if (this.state === s) return;
    this.state = s;
    for (const cb of [...this.stateCbs]) cb(s);
  }

  private diagnose(line: string): void {
    for (const cb of [...this.diagCbs]) cb(line);
  }

  // ---- lifecycle ---------------------------------------------------------

  /**
   * Spawn the worker and run `engine.handshake`. Resolves with the
   * handshake result once the engine is `ready`. Rejects on spawn failure,
   * timeout, or a PROTOCOL_VERSION_MISMATCH refusal (the worker then exits
   * and `crashed` is signalled via the exit path).
   */
  async start(): Promise<HandshakeResult> {
    if (this.state !== "idle") {
      throw new SidecarError(
        ERR.ENGINE_NOT_READY,
        `client.start() from state '${this.state}'`,
      );
    }
    this.setState("starting");
    try {
      await this.port.start();
    } catch (e) {
      this.setState("crashed");
      throw e instanceof SidecarError
        ? e
        : new SidecarError(ERR.ENGINE_UNAVAILABLE, String(e));
    }
    let result: HandshakeResult;
    try {
      result = (await this.requestRaw(
        "engine.handshake",
        {
          protocolVersion: PROTOCOL_VERSION,
          clientInfo: { name: "hornscribe-desktop", surface: "react" },
        },
        this.opts.handshakeTimeoutMs,
        /* allowBeforeReady */ true,
      )) as HandshakeResult;
    } catch (e) {
      // Timeout / refusal / dead port — never leave the client wedged in
      // "starting"; the exit event may also mark it crashed, both are dead.
      if (this.getState() === "starting") this.setState("crashed");
      throw e;
    }
    if (result.protocolVersion !== PROTOCOL_VERSION) {
      this.setState("crashed");
      throw new SidecarError(
        ERR.PROTOCOL_VERSION_MISMATCH,
        `worker reported protocolVersion ${String(result.protocolVersion)}`,
      );
    }
    this.handshakeResult = result;
    this.setState("ready");
    return result;
  }

  /** Graceful shutdown: `engine.shutdown`, then stdin EOF fallback, and
   *  finally a bounded wait for the exit event. Never throws. */
  async shutdown(timeoutMs = 3_000): Promise<void> {
    if (this.state === "closed" || this.state === "crashed") {
      this.setState("closed");
      return;
    }
    this.shutdownRequested = true;
    try {
      if (this.state === "ready") {
        await this.requestRaw<ShutdownResult>(
          "engine.shutdown",
          {},
          Math.min(timeoutMs, this.opts.requestTimeoutMs),
          true,
        );
      }
    } catch {
      // The worker may already be gone — stdin EOF below is the fallback.
    }
    try {
      this.port.closeStdin();
    } catch {
      /* port already dead */
    }
    // Bounded wait for the exit event; then mark closed regardless —
    // shutdown must not hang the UI.
    const deadline = Date.now() + timeoutMs;
    while (
      this.getState() !== "closed" &&
      this.getState() !== "crashed" &&
      Date.now() < deadline
    ) {
      await new Promise((r) => setTimeout(r, 15));
    }
    this.clearWatchdog();
    this.rejectAllPending(new SidecarError(ERR.ENGINE_NOT_READY, "client shut down"));
    this.setState("closed");
  }

  /** Liveness + latency probe. */
  async ping(echo: unknown = null): Promise<PingResult> {
    return this.request<PingResult>("engine.ping", { echo });
  }

  /** `job.start` — returns {jobId, jobKind, state:"accepted"}.
   *  JOB_ALREADY_RUNNING is enforced engine-side. */
  async startJob(jobKind: string, params: unknown): Promise<JobStartResult> {
    const res = await this.request<JobStartResult>("job.start", {
      jobKind,
      params,
    });
    this.activeJobs.add(res.jobId);
    this.armWatchdog();
    return res;
  }

  /** `job.cancel` — cooperative: the job emits its terminal `cancelled`
   *  event at the next checkpoint. JOB_NOT_FOUND means it already ended. */
  async cancelJob(jobId: string): Promise<JobCancelResult> {
    return this.request<JobCancelResult>("job.cancel", { jobId });
  }

  // ---- requests -----------------------------------------------------------

  private async request<T>(method: string, payload: unknown): Promise<T> {
    return this.requestRaw<T>(method, payload, this.opts.requestTimeoutMs, false);
  }

  private requestRaw<T>(
    method: string,
    payload: unknown,
    timeoutMs: number,
    allowBeforeReady: boolean,
  ): Promise<T> {
    if (!allowBeforeReady && this.state !== "ready") {
      return Promise.reject(
        new SidecarError(
          ERR.ENGINE_NOT_READY,
          `cannot issue '${method}' while client is '${this.state}'`,
        ),
      );
    }
    this.counter += 1;
    const id = `req-${String(this.counter).padStart(6, "0")}`;
    return new Promise<T>((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pending.delete(id);
        reject(
          new SidecarError(
            ERR.REQUEST_TIMEOUT,
            `no response to '${method}' within ${timeoutMs}ms`,
            { method, id },
          ),
        );
      }, timeoutMs);
      this.pending.set(id, {
        method,
        resolve: resolve as (p: unknown) => void,
        reject,
        timer,
      });
      try {
        this.port.writeLine(encodeFrame(requestFrame(id, method, payload)));
      } catch (e) {
        clearTimeout(timer);
        this.pending.delete(id);
        reject(
          e instanceof SidecarError
            ? e
            : new SidecarError(ERR.ENGINE_UNAVAILABLE, String(e)),
        );
      }
    });
  }

  // ---- inbound frames -------------------------------------------------------

  private handleLine(line: string): void {
    this.touch();
    const frame = parseInboundFrame(line);
    if (!frame) {
      this.diagnose(`dropped malformed inbound frame: ${line.slice(0, 200)}`);
      return;
    }
    if (frame.kind === "response") {
      this.handleResponse(frame.id, frame.method, frame.payload, frame.error);
    } else {
      this.handleEvent(frame.method, frame.payload);
    }
  }

  private handleResponse(
    id: string | null,
    method: string | null,
    payload: unknown,
    error: ProtocolErrorObject | null,
  ): void {
    if (id === null) {
      // The one sanctioned null-id response: the worker could not recover
      // an id from a frame it rejected. We never send unrecoverable
      // frames, so this is a diagnostics curiosity, not a request result.
      this.diagnose(
        `null-id error response (${method ?? "?"}): ${error?.code ?? "?"} ${error?.message ?? ""}`,
      );
      return;
    }
    const pending = this.pending.get(id);
    if (!pending) {
      this.diagnose(`response for unknown id '${id}' dropped`);
      return;
    }
    clearTimeout(pending.timer);
    this.pending.delete(id);
    if (error) {
      pending.reject(new SidecarError(error.code, error.message, error.details));
    } else {
      pending.resolve(payload);
    }
  }

  private handleEvent(method: string | null, payload: unknown): void {
    if (method !== "job.event") {
      this.diagnose(`event '${method ?? "?"}' dropped (no subscriber)`);
      return;
    }
    const body = (payload ?? {}) as JobEventPayload;
    if (typeof body.jobId !== "string" || typeof body.phase !== "string") {
      this.diagnose("job.event without jobId/phase dropped");
      return;
    }
    if (isTerminalPhase(body.phase)) {
      this.activeJobs.delete(body.jobId);
      if (this.activeJobs.size === 0) this.clearWatchdog();
    }
    for (const cb of [...this.jobEventCbs]) cb(body);
  }

  // ---- crash / watchdog ------------------------------------------------------

  private touch(): void {
    if (this.activeJobs.size > 0 && this.state === "ready") this.armWatchdog();
  }

  private armWatchdog(): void {
    this.clearWatchdog();
    if (this.state !== "ready" || this.activeJobs.size === 0) return;
    this.watchdogTimer = setTimeout(() => void this.probe(), this.opts.watchdogMs);
  }

  private clearWatchdog(): void {
    if (this.watchdogTimer !== null) {
      clearTimeout(this.watchdogTimer);
      this.watchdogTimer = null;
    }
  }

  /** Watchdog probe: the job produced no frames for watchdogMs — ping the
   *  worker; if even that times out, declare it unresponsive. */
  private async probe(): Promise<void> {
    if (this.probing || this.state !== "ready" || this.activeJobs.size === 0) {
      return;
    }
    this.probing = true;
    try {
      await this.requestRaw(
        "engine.ping",
        { echo: "watchdog" },
        this.opts.pingTimeoutMs,
        true,
      );
      // Alive — re-arm. A busy worker answers ping even mid-job (the
      // dispatch loop is independent of the job thread).
      this.armWatchdog();
    } catch {
      this.setState("unresponsive");
      this.clearWatchdog();
      this.diagnose("worker did not answer watchdog ping — unresponsive");
      this.rejectAllPending(
        new SidecarError(ERR.WORKER_UNRESPONSIVE, "worker is not responding"),
      );
    } finally {
      this.probing = false;
    }
  }

  private handleExit(code: number | null): void {
    this.clearWatchdog();
    const graceful = this.shutdownRequested || code === 0;
    this.rejectAllPending(
      new SidecarError(
        graceful ? ERR.ENGINE_NOT_READY : ERR.WORKER_CRASHED,
        graceful ? "worker shut down" : `worker exited (code ${String(code)})`,
      ),
    );
    this.setState(graceful ? "closed" : "crashed");
    if (!graceful) {
      this.diagnose(`worker exited unexpectedly (code ${String(code)})`);
    }
  }

  private rejectAllPending(err: SidecarError): void {
    for (const [, p] of this.pending) {
      clearTimeout(p.timer);
      p.reject(err);
    }
    this.pending.clear();
  }
}

