/**
 * SidecarPort — the transport seam between the typed NDJSON client and a
 * concrete worker process.
 *
 * The port owns process lifecycle only: it delivers whole stdout lines to
 * the client and accepts whole request lines back. It knows nothing about
 * the protocol (no JSON parsing) — that layering mirrors the UI-002 test
 * harness (`WorkerHandle`), which is why the same client runs against the
 * in-process MockSidecarPort and, later, a Tauri-spawned worker unchanged.
 *
 * ## Packaged-app gate (UI-040)
 *
 * A real worker is spawned by the Tauri shell. This branch deliberately
 * does NOT widen `src-tauri/capabilities/default.json`: it grants no
 * shell/process plugin today and no `tauri-plugin-*` dependency exists in
 * `src-tauri/Cargo.toml`. The intended production port is a small Rust
 * supervisor that spawns `python -m hornscribe.worker` (or the frozen
 * engine executable), pipes stdin/stdout, and forwards lines to the
 * frontend — reachable either through `tauri-plugin-shell`'s `Command`
 * events or an app-defined `invoke` + `Channel` (app commands are not
 * capability-gated). Until that lands, `createDefaultSidecarPort()` returns
 * {@link UnsupportedSidecarPort} inside the Tauri webview so the failure is
 * explicit and recoverable, never a silent mock.
 */

import { ERR, SidecarError } from "./protocol";
import { MockSidecarPort } from "./mockPort";
import { isTauriRuntime } from "../tauri/bridge";

export interface SidecarPort {
  /**
   * Spawn/attach the worker. Resolves when the process is up and its
   * stdin is writable — the protocol handshake happens after this, on the
   * client. Rejects when the worker cannot be launched at all.
   */
  start(): Promise<void>;
  /** Write one NDJSON frame to the worker's stdin (a newline is appended). */
  writeLine(line: string): void;
  /**
   * Close the worker's stdin — the worker treats EOF as an implicit
   * graceful `engine.shutdown` (worker.py contract).
   */
  closeStdin(): void;
  /**
   * Terminate the worker immediately. This is the documented
   * terminate/restart fallback for non-interruptible jobs and the
   * unresponsive-worker path (ENGINE_RUNTIME_MATRIX / ADR-0002).
   */
  kill(): void;
  /** Subscribe to raw stdout lines. Returns an unsubscribe function. */
  onLine(cb: (line: string) => void): () => void;
  /** Subscribe to stderr lines (diagnostics only, never protocol). */
  onStderr(cb: (line: string) => void): () => void;
  /**
   * Subscribe to process exit. Fires exactly once. `code` is the exit
   * code, or null when it cannot be determined (e.g. killed by signal).
   */
  onExit(cb: (code: number | null) => void): () => void;
}

/**
 * Placeholder port for environments where no spawn bridge exists yet —
 * currently every real Tauri runtime (see the gate note above). `start()`
 * fails explicitly with ENGINE_UNAVAILABLE; the session maps that to the
 * worker-not-responding recovery surface, so the packaged shell degrades
 * honestly instead of pretending a mock engine is real.
 */
export class UnsupportedSidecarPort implements SidecarPort {
  async start(): Promise<void> {
    throw new SidecarError(
      ERR.ENGINE_UNAVAILABLE,
      "engine sidecar spawn is not wired into the Tauri shell yet " +
        "(requires a process bridge; see src/sidecar/README.md)",
    );
  }
  writeLine(): void {
    throw new SidecarError(ERR.ENGINE_UNAVAILABLE, "sidecar port is unavailable");
  }
  closeStdin(): void {
    /* no worker */
  }
  kill(): void {
    /* no worker */
  }
  onLine(): () => void {
    return () => undefined;
  }
  onStderr(): () => void {
    return () => undefined;
  }
  onExit(): () => void {
    return () => undefined;
  }
}

/**
 * The port used when no explicit one is injected:
 * - inside the Tauri webview: {@link UnsupportedSidecarPort} (gated — see
 *   the note at the top of this file);
 * - in a plain browser (`vite dev`): {@link MockSidecarPort}, an
 *   in-process emulation of `python -m hornscribe.worker` that speaks the
 *   real NDJSON contract so the whole transcription UX is exercisable
 *   without a Python runtime.
 */
export function createDefaultSidecarPort(): SidecarPort {
  if (isTauriRuntime()) return new UnsupportedSidecarPort();
  return new MockSidecarPort();
}

/**
 * Client-side mirror of the HornScribe NDJSON sidecar protocol
 * (protocol/PROTOCOL.md, implemented engine-side by
 * python/hornscribe/worker/protocol.py).
 *
 * Transport: one JSON envelope per line over the sidecar's stdin/stdout;
 * stderr is diagnostics only. Unknown additive fields are ignored safely
 * (ADR-0002), so every payload type below carries an index signature.
 */

/** Wire protocol version implemented by this client. */
export const PROTOCOL_VERSION = 1;

/** Structured error object carried inside an envelope or a job event. */
export interface ProtocolErrorObject {
  code: string;
  message: string;
  details?: unknown;
}

export type FrameKind = "request" | "response" | "event";

/** The wire envelope — a single JSON object per NDJSON line. */
export interface Envelope {
  v: number;
  id: string | null;
  kind: FrameKind;
  method: string | null;
  payload: unknown;
  error: ProtocolErrorObject | null;
}

/**
 * Error codes. UPPER_SNAKE per PROTOCOL.md. The first block mirrors
 * python/hornscribe/worker/protocol.py exactly; the second block is
 * shell-side supervision codes that never appear on the wire — they mark
 * failures the supervisor (this client) detected itself, mirroring how the
 * UI-002 test harness marks an in-flight job failed when the worker dies
 * mid-job (ADR-0002: never silently resubmitted).
 */
export const ERR = {
  PROTOCOL_VERSION_MISMATCH: "PROTOCOL_VERSION_MISMATCH",
  MALFORMED_MESSAGE: "MALFORMED_MESSAGE",
  UNKNOWN_METHOD: "UNKNOWN_METHOD",
  INVALID_PARAMS: "INVALID_PARAMS",
  JOB_NOT_FOUND: "JOB_NOT_FOUND",
  JOB_ALREADY_RUNNING: "JOB_ALREADY_RUNNING",
  UNKNOWN_JOB_KIND: "UNKNOWN_JOB_KIND",
  JOB_TIMEOUT: "JOB_TIMEOUT",
  JOB_FAILED: "JOB_FAILED",
  INTERNAL_ERROR: "INTERNAL_ERROR",
  // ---- shell-side supervision codes (not wire codes) ----
  /** The worker process exited without a graceful shutdown. */
  WORKER_CRASHED: "WORKER_CRASHED",
  /** Watchdog: the worker stopped answering while a job was in flight. */
  WORKER_UNRESPONSIVE: "WORKER_UNRESPONSIVE",
  /** A request received no response within its timeout. */
  REQUEST_TIMEOUT: "REQUEST_TIMEOUT",
  /** The sidecar transport could not be started (e.g. spawn gate). */
  ENGINE_UNAVAILABLE: "ENGINE_UNAVAILABLE",
  /** A request was issued while the client was not in `ready` state. */
  ENGINE_NOT_READY: "ENGINE_NOT_READY",
} as const;

export type ErrorCode = (typeof ERR)[keyof typeof ERR];

/** Structured failure raised by the client — converts an error object to
 *  an exception so callers can `catch` instead of checking envelopes. */
export class SidecarError extends Error {
  readonly code: string;
  readonly details?: unknown;

  constructor(code: string, message: string, details?: unknown) {
    super(message);
    this.name = "SidecarError";
    this.code = code;
    this.details = details;
  }
}

// ---- envelope builders (client → worker) -----------------------------

export function requestFrame(
  id: string,
  method: string,
  payload: unknown,
): Envelope {
  return { v: PROTOCOL_VERSION, id, kind: "request", method, payload, error: null };
}

/** Serialize an envelope to a single NDJSON line (no trailing newline —
 *  the port adds it). JSON.stringify escapes control characters so the
 *  output can never contain a raw newline. */
export function encodeFrame(envelope: Envelope): string {
  return JSON.stringify(envelope);
}

// ---- inbound parsing ---------------------------------------------------

/**
 * Parse one inbound NDJSON line into an Envelope, or return null when the
 * frame is too malformed to use. Client-side parsing is deliberately
 * tolerant about *content* (unknown fields pass through per ADR-0002) but
 * strict about envelope shape: a frame we cannot route is dropped and
 * reported through the diagnostics channel, never answered.
 */
export function parseInboundFrame(line: string): Envelope | null {
  const text = line.trim();
  if (!text) return null;
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    return null;
  }
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    return null;
  }
  const frame = raw as Record<string, unknown>;
  if (frame.v !== PROTOCOL_VERSION) return null;
  const kind = frame.kind;
  if (kind !== "response" && kind !== "event") {
    // The worker only ever sends responses and events; anything else
    // (including inbound "request") is logged and dropped, never answered.
    return null;
  }
  const id = frame.id;
  const method = frame.method;
  if (kind === "response") {
    // A response carries the request id — except the single sanctioned
    // `id: null` case (worker could not recover an id from our frame),
    // which also arrives with `method: null`.
    if (id !== null && (typeof id !== "string" || !id)) return null;
    if (id === null) {
      if (method !== null && method !== undefined && typeof method !== "string") {
        return null;
      }
    } else if (typeof method !== "string" || !method) {
      return null;
    }
  } else {
    // Events must carry exactly `id: null` and a non-empty method.
    if (id !== null) return null;
    if (typeof method !== "string" || !method) return null;
  }
  const error = normalizeError(frame.error);
  return {
    v: PROTOCOL_VERSION,
    id: (id as string | null) ?? null,
    kind,
    // `undefined` (absent field) normalizes to null — the wire contract
    // always carries the key, but a tolerantly-typed frame may omit it.
    method: (method as string | null | undefined) ?? null,
    payload: frame.payload,
    error,
  };
}

function normalizeError(raw: unknown): ProtocolErrorObject | null {
  if (raw === null || raw === undefined) return null;
  if (typeof raw !== "object") return null;
  const e = raw as Record<string, unknown>;
  if (typeof e.code !== "string" || typeof e.message !== "string") return null;
  return { code: e.code, message: e.message, details: e.details };
}

// ---- method payloads -----------------------------------------------------

export interface EngineInfo {
  name?: string;
  version?: string;
  python?: string;
  platform?: string;
  pid?: number;
  [key: string]: unknown;
}

export interface EngineCapabilities {
  methods?: string[];
  jobKinds?: string[];
  maxConcurrentJobs?: number;
  cooperativeCancel?: boolean;
  cancellationFallback?: string;
  progressEvents?: boolean;
  basicPitchAvailable?: boolean;
  [key: string]: unknown;
}

export interface HandshakeResult {
  protocolVersion: number;
  engineInfo: EngineInfo;
  capabilities: EngineCapabilities;
  [key: string]: unknown;
}

export interface PingResult {
  echo: unknown;
  workerPid?: number;
  uptimeMs?: number;
  [key: string]: unknown;
}

export interface ShutdownResult {
  ok: boolean;
  activeJob: string | null;
  [key: string]: unknown;
}

export interface JobStartResult {
  jobId: string;
  jobKind: string;
  state: string;
  [key: string]: unknown;
}

export interface JobCancelResult {
  jobId: string;
  cancellation: string;
  [key: string]: unknown;
}

/** `job.event` terminal phases: exactly one ends every job. */
export type JobTerminalPhase = "completed" | "cancelled" | "failed";
export type JobPhase = "started" | "progress" | JobTerminalPhase;

/**
 * `job.event` payload (kind=event, id=null).
 *
 * [UI-040] additive fields beyond the UI-002 spike contract:
 * - `stage`: pipeline stage id (TRANSCRIPTION_STAGE_IDS) reported by jobs
 *   that can name their position honestly. Absent for stage-less jobs
 *   (e.g. `demoLongTask` on the spike worker) — the UI must not infer one.
 * - `result.reviewIssues` on `completed`: ReviewIssue dicts
 *   (python/hornscribe/domain/review.py `ReviewIssue.to_dict`).
 */
export interface JobEventPayload {
  jobId: string;
  jobKind?: string;
  phase: JobPhase;
  /** Real 0–1 job fraction when the engine can compute one — may be absent. */
  progress?: number;
  /** [UI-040] current pipeline stage id — absent when unknown. */
  stage?: string;
  step?: number;
  totalSteps?: number;
  /** `failed` terminal events carry the job error here (envelope error stays null). */
  error?: ProtocolErrorObject;
  /** `completed` events may carry the job result payload. */
  result?: unknown;
  [key: string]: unknown;
}

export function isTerminalPhase(phase: string): phase is JobTerminalPhase {
  return phase === "completed" || phase === "cancelled" || phase === "failed";
}

/**
 * TypeScript mirror of the engine's ReviewIssue contract
 * (python/hornscribe/domain/review.py, MASTER_PLAN §10).
 *
 * The UI consumes product-level review items — it never interprets raw
 * backend confidence. `reason` maps onto `review.reasons.<reason>` in the
 * copy deck; unknown future reasons fall back to `review.reasons.other`
 * (UI_COPY_CONTRACT §4). The deck knows more reasons than the current
 * engine enum — that is fine (additive), the fallback covers the rest.
 */

/** Engine-side reason codes — mirrors `ReviewReason` in review.py. */
export const REVIEW_REASONS = [
  "low_model_confidence",
  "very_short_detection",
  "overlapping_candidates",
  "quantization_ambiguous",
  "pitch_spelling_ambiguous",
  "outside_preferred_horn_range",
  "structural_measure_conflict",
] as const;

export type ReviewReason = (typeof REVIEW_REASONS)[number];

/** Copy-deck reason keys (`review.reasons.*` in protocol/copy/ja-JP.json).
 *  A superset of the engine enum — newer decks may carry reasons the
 *  engine does not emit yet. */
export const REVIEW_REASON_COPY_KEYS = [
  "low_model_confidence",
  "very_short_detection",
  "overlapping_candidates",
  "quantization_ambiguous",
  "pitch_spelling_ambiguous",
  "outside_preferred_horn_range",
  "structural_measure_conflict",
  "beat_alignment_uncertain",
  "beat_map_uncertain",
  "possible_triplet",
  "possible_grace_note",
  "offset_ambiguous",
  "pickup_ambiguous",
  "meter_conflict",
  "onset_uncertain",
  "pitch_uncertain",
  "multiple_candidates",
  "other",
] as const;

export type ReviewReasonCopyKey = (typeof REVIEW_REASON_COPY_KEYS)[number];

/** Copy-deck key for a reason code — `other` for anything unknown. */
export function reviewReasonCopyKey(reason: string): ReviewReasonCopyKey {
  return (REVIEW_REASON_COPY_KEYS as readonly string[]).includes(reason)
    ? (reason as ReviewReasonCopyKey)
    : "other";
}

export const REVIEW_SEVERITIES = ["info", "caution", "warning"] as const;
export type ReviewSeverity = (typeof REVIEW_SEVERITIES)[number];

export const REVIEW_ISSUE_STATUSES = [
  "open",
  "accepted",
  "dismissed",
  "fixed",
] as const;
export type ReviewIssueStatus = (typeof REVIEW_ISSUE_STATUSES)[number];

/** `ReviewIssue.to_dict()` shape — camelCase per the project schema. */
export interface ReviewIssuePayload {
  id: string;
  scoreRevision: string;
  canonicalNoteIds: string[];
  timeRange: { startSec: number; endSec: number };
  reason: string;
  severity: string;
  evidence: Record<string, unknown>;
  status: string;
  [key: string]: unknown;
}

export function isReviewIssuePayload(raw: unknown): raw is ReviewIssuePayload {
  if (typeof raw !== "object" || raw === null) return false;
  const r = raw as Record<string, unknown>;
  return typeof r.id === "string" && typeof r.reason === "string";
}

/**
 * Open (unresolved) review issues carried by a completed job's
 * `result.reviewIssues` field. The contract consumed here is the handoff
 * point documented for UI-030's score-data adapter: UI-040 only needs the
 * count for the command bar / review gate, so unknown entries count as
 * issues rather than being silently dropped.
 */
export function extractReviewIssues(result: unknown): ReviewIssuePayload[] {
  if (typeof result !== "object" || result === null) return [];
  const raw = (result as Record<string, unknown>).reviewIssues;
  if (!Array.isArray(raw)) return [];
  return raw.filter(isReviewIssuePayload);
}

/** `result.reviewIssues.length`, with `result.reviewIssueCount` as a
 *  compact alternative the engine may emit instead of the full list. */
export function extractReviewIssueCount(result: unknown): number {
  const issues = extractReviewIssues(result);
  if (issues.length > 0) return issues.length;
  if (typeof result !== "object" || result === null) return 0;
  const raw = (result as Record<string, unknown>).reviewIssueCount;
  return typeof raw === "number" && raw > 0 ? Math.floor(raw) : 0;
}

/**
 * TranscriptionSession + jobView tracker tests (UI-040).
 *
 * Covers the app-facing state machine: start → stage/progress tracking →
 * terminal transitions, cooperative cancel with the honest `cancelling`
 * state, job failure → 再試行 surface, worker crash/unresponsive →
 * エンジンを再起動 recovery, review-issue count extraction, and the
 * stage-honesty rules (no `stage` field → no claimed position).
 */

import { describe, expect, it } from "vitest";
import { MockSidecarPort } from "./mockPort";
import {
  TranscriptionSession,
  type SessionSnapshot,
} from "./session";
import {
  createJobView,
  initialStages,
  markCancelling,
  markJobDead,
  reduceJobEvent,
  TRANSCRIPTION_STAGE_IDS,
} from "./jobView";
import {
  extractReviewIssueCount,
  reviewReasonCopyKey,
} from "./review";
import { ERR, type JobEventPayload } from "./protocol";

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function until(cond: () => boolean, ms = 1500): Promise<void> {
  const deadline = Date.now() + ms;
  while (!cond()) {
    if (Date.now() > deadline) throw new Error("timed out waiting for condition");
    await sleep(2);
  }
}

function makeSession(port = new MockSidecarPort()) {
  const session = new TranscriptionSession({
    portFactory: () => port,
    clientOptions: {
      requestTimeoutMs: 250,
      handshakeTimeoutMs: 500,
      watchdogMs: 40,
      pingTimeoutMs: 30,
    },
  });
  const snaps: SessionSnapshot[] = [];
  session.subscribe((s) => snaps.push(s));
  return { session, port, snaps };
}

const FAST = { steps: 7, stepDurationMs: 2 };

describe("jobView tracker (pure)", () => {
  const ev = (over: Partial<JobEventPayload>): JobEventPayload => ({
    jobId: "job-1",
    phase: "progress",
    ...over,
  });

  it("stages advance only on reported stage fields, in order", () => {
    let v = createJobView("job-1", "transcription", 0);
    expect(v.stages.every((s) => s.status === "pending")).toBe(true);
    v = reduceJobEvent(v, ev({ stage: "preparing_audio" }));
    expect(v.stages[0].status).toBe("active");
    v = reduceJobEvent(v, ev({ stage: "quantizing", progress: 0.6 }));
    expect(v.stages[0].status).toBe("done");
    expect(v.stages[4].status).toBe("active");
    expect(v.activeStageIndex).toBe(4);
    expect(v.progress).toBeCloseTo(0.6);
  });

  it("ignores unknown stage ids and out-of-order noise safely", () => {
    let v = createJobView("job-1", "transcription", 0);
    v = reduceJobEvent(v, ev({ stage: "not_a_stage" }));
    expect(v.stages.every((s) => s.status === "pending")).toBe(true);
    expect(v.hasStageInfo).toBe(false);
    // A stage going "backwards" is ignored (monotonic honesty).
    v = reduceJobEvent(v, ev({ stage: "building_score" }));
    v = reduceJobEvent(v, ev({ stage: "preparing_audio" }));
    expect(v.activeStageIndex).toBe(5);
  });

  it("a job without stage info stays honest (all pending, real progress)", () => {
    let v = createJobView("job-1", "demoLongTask", 0);
    v = reduceJobEvent(v, ev({ progress: 0.4 }));
    v = reduceJobEvent(v, ev({ progress: 0.7 }));
    expect(v.hasStageInfo).toBe(false);
    expect(v.stages.every((s) => s.status === "pending")).toBe(true);
    expect(v.progress).toBeCloseTo(0.7);
  });

  it("terminal completed marks every stage done; later events are ignored", () => {
    let v = createJobView("job-1", "transcription", 0);
    v = reduceJobEvent(v, ev({ stage: "transcribing" }));
    v = reduceJobEvent(v, ev({ phase: "completed", result: { ok: true } }));
    expect(v.phase).toBe("completed");
    expect(v.stages.every((s) => s.status === "done")).toBe(true);
    const after = reduceJobEvent(v, ev({ stage: "preparing_audio" }));
    expect(after.stages[0].status).toBe("done"); // unchanged
  });

  it("failed carries the job error; cancelled preserves position", () => {
    let v = createJobView("job-1", "transcription", 0);
    v = reduceJobEvent(v, ev({ stage: "cleaning" }));
    const f = reduceJobEvent(
      v,
      ev({ phase: "failed", error: { code: "JOB_FAILED", message: "x" } }),
    );
    expect(f.phase).toBe("failed");
    expect(f.error?.code).toBe("JOB_FAILED");
    expect(f.stages[2].status).toBe("active"); // where it died
    const c = reduceJobEvent(v, ev({ phase: "cancelled" }));
    expect(c.phase).toBe("cancelled");
    expect(c.stages[2].status).toBe("active");
  });

  it("markCancelling only applies while running; markJobDead is terminal", () => {
    let v = createJobView("job-1", "transcription", 0);
    v = markCancelling(v);
    expect(v.phase).toBe("cancelling");
    const dead = markJobDead(v, { code: ERR.WORKER_CRASHED, message: "x" });
    expect(dead.phase).toBe("failed");
    expect(dead.error?.code).toBe(ERR.WORKER_CRASHED);
    // A settled job is never resurrected.
    const done = reduceJobEvent(dead, {
      jobId: "job-1",
      phase: "completed",
    });
    expect(done.phase).toBe("failed");
  });

  it("stage ids cover the copy deck order (7 stages)", () => {
    expect(TRANSCRIPTION_STAGE_IDS).toEqual([
      "preparing_audio",
      "transcribing",
      "cleaning",
      "analyzing_rhythm",
      "quantizing",
      "building_score",
      "rendering",
    ]);
    expect(initialStages()).toHaveLength(7);
  });
});

describe("review contract", () => {
  it("extracts the open-issue count from a completed result", () => {
    expect(
      extractReviewIssueCount({ reviewIssues: [{ id: "ri-1", reason: "x" }] }),
    ).toBe(1);
    expect(extractReviewIssueCount({ reviewIssueCount: 5 })).toBe(5);
    expect(extractReviewIssueCount({})).toBe(0);
    expect(extractReviewIssueCount(null)).toBe(0);
    expect(extractReviewIssueCount({ reviewIssues: "nope" })).toBe(0);
  });

  it("maps known reasons to deck keys, unknown to 'other'", () => {
    expect(reviewReasonCopyKey("quantization_ambiguous")).toBe(
      "quantization_ambiguous",
    );
    expect(reviewReasonCopyKey("low_model_confidence")).toBe(
      "low_model_confidence",
    );
    expect(reviewReasonCopyKey("future_reason_x")).toBe("other");
  });
});

describe("TranscriptionSession", () => {
  it("starts the engine lazily and runs a job to completion", async () => {
    const { session, snaps } = makeSession();
    await session.startTranscription(FAST);
    expect(session.getSnapshot().engine).toBe("ready");
    await until(() => session.getSnapshot().job?.phase === "completed");
    const s = session.getSnapshot();
    expect(s.reviewIssueCount).toBe(3); // mock transcription result
    expect(s.lastResult).toMatchObject({ scoreRevision: "sr-mock-0001" });
    // Stages advanced through the pipeline for a stage-aware kind.
    const job = s.job!;
    expect(job.stages.every((st) => st.status === "done")).toBe(true);
    expect(snaps.some((x) => x.engine === "starting")).toBe(true);
    await session.dispose();
  });

  it("falls back to demoLongTask when the engine lacks 'transcription'", async () => {
    const port = new MockSidecarPort({ jobKinds: ["demoLongTask"] });
    const { session } = makeSession(port);
    await session.startTranscription({ steps: 2, stepDurationMs: 1 });
    const job = session.getSnapshot().job;
    expect(job?.jobKind).toBe("demoLongTask");
    await until(() => session.getSnapshot().job?.phase === "completed");
    await session.dispose();
  });

  it("cancel → cancelling (honest pending) → terminal cancelled", async () => {
    const { session, snaps } = makeSession();
    await session.startTranscription({ steps: 50, stepDurationMs: 4 });
    await until(() => session.getSnapshot().job?.phase === "running");
    await session.cancelTranscription();
    // The ack turns the view to cancelling BEFORE the terminal event —
    // the button's pending state is honest, not instant.
    expect(snaps.some((s) => s.job?.phase === "cancelling")).toBe(true);
    await until(() => session.getSnapshot().job?.phase === "cancelled");
    await session.dispose();
  });

  it("job failure sets transcriptionFailed (再試行 surface), engine stays ready", async () => {
    const { session } = makeSession();
    await session.startTranscription({
      steps: 10,
      stepDurationMs: 2,
      failAtStep: 2,
    });
    await until(() => session.getSnapshot().failure !== null);
    const s = session.getSnapshot();
    expect(s.failure?.kind).toBe("transcriptionFailed");
    expect(s.job?.phase).toBe("failed");
    expect(s.engine).toBe("ready"); // engine alive → retry is meaningful
    await session.dispose();
  });

  it("explicit retry after failure runs a fresh job", async () => {
    const { session } = makeSession();
    await session.startTranscription({ steps: 10, stepDurationMs: 2, failAtStep: 2 });
    await until(() => session.getSnapshot().failure !== null);
    session.clearFailure();
    await session.startTranscription(FAST); // explicit retry — never silent
    await until(() => session.getSnapshot().job?.phase === "completed");
    expect(session.getSnapshot().failure).toBeNull();
    await session.dispose();
  });

  it("a mid-job crash fails the job and offers workerCrashed recovery", async () => {
    const { session, port } = makeSession();
    await session.startTranscription({ steps: 100, stepDurationMs: 5 });
    await until(
      () => (session.getSnapshot().job?.progress ?? 0) > 0,
    );
    port.simulateCrash();
    await until(() => session.getSnapshot().failure !== null);
    const s = session.getSnapshot();
    expect(s.engine).toBe("crashed");
    expect(s.failure?.kind).toBe("workerCrashed");
    // ADR-0002: the job is marked failed by the supervisor — the worker
    // emitted no terminal event.
    expect(s.job?.phase).toBe("failed");
    expect(s.job?.error?.code).toBe(ERR.WORKER_CRASHED);
    await session.dispose();
  });

  it("restartEngine recovers a crashed worker with a fresh handshake", async () => {
    const port = new MockSidecarPort();
    let n = 0;
    const session = new TranscriptionSession({
      portFactory: () => (n++ === 0 ? port : new MockSidecarPort()),
      clientOptions: { watchdogMs: 40, pingTimeoutMs: 30 },
    });
    await session.startTranscription({ steps: 100, stepDurationMs: 5 });
    await until(() => (session.getSnapshot().job?.progress ?? 0) > 0);
    port.simulateCrash();
    await until(() => session.getSnapshot().engine === "crashed");
    await session.restartEngine();
    const s = session.getSnapshot();
    expect(s.engine).toBe("ready");
    expect(s.engineInfo?.name).toBe("hornscribe-engine");
    // The dead job is NOT silently resubmitted — user decides.
    await session.dispose();
  });

  it("watchdog unresponsiveness mid-job sets workerNotResponding", async () => {
    const { session, port } = makeSession();
    await session.startTranscription({ steps: 100, stepDurationMs: 5 });
    await until(() => (session.getSnapshot().job?.progress ?? 0) > 0);
    port.simulateHang();
    await until(() => session.getSnapshot().failure !== null, 2000);
    const s = session.getSnapshot();
    expect(s.engine).toBe("unresponsive");
    expect(s.failure?.kind).toBe("workerNotResponding");
    expect(s.job?.error?.code).toBe(ERR.WORKER_UNRESPONSIVE);
    await session.dispose();
  });

  it("an idle crash reports engine state without a failure surface", async () => {
    const { session, port } = makeSession();
    await session.startTranscription(FAST);
    await until(() => session.getSnapshot().job?.phase === "completed");
    session.clearJob();
    port.simulateCrash();
    await until(() => session.getSnapshot().engine === "crashed");
    // No job in flight → no modal error; the status bar shows the crash.
    expect(session.getSnapshot().failure).toBeNull();
    await session.dispose();
  });

  it("double start while a job is running is rejected", async () => {
    const { session } = makeSession();
    await session.startTranscription({ steps: 50, stepDurationMs: 5 });
    await expect(session.startTranscription(FAST)).rejects.toMatchObject({
      code: ERR.JOB_ALREADY_RUNNING,
    });
    await session.dispose();
  });

  it("a job.start that gets no response fails honestly (no stuck screen)", async () => {
    const { session, port } = makeSession();
    // Warm the engine to ready, then wedge it before the next start so
    // job.start itself times out — the screen must land on the failure
    // surface, not on a phantom running job.
    await session.startTranscription({ steps: 1, stepDurationMs: 1 });
    await until(() => session.getSnapshot().job?.phase === "completed");
    session.clearJob();
    port.simulateHang();
    await expect(
      session.startTranscription({ steps: 5, stepDurationMs: 5 }),
    ).rejects.toMatchObject({ code: ERR.REQUEST_TIMEOUT });
    const s = session.getSnapshot();
    expect(s.failure?.kind).toBe("transcriptionFailed");
    expect(s.job).toBeNull();
    await session.dispose();
  });
});

/**
 * TranscriptionSession — the app-facing engine/job state machine
 * (GUI_UX_SPEC §5, §27; ADR-0002 failure model).
 *
 * One job at a time (the worker enforces `maxConcurrentJobs: 1`).
 * The session owns a {@link SidecarClient} built on a port factory, so a
 * crashed worker can be replaced by a fresh spawn without restarting the
 * UI — restart is an explicit recovery action, never silent resubmission.
 *
 * State is exposed as an immutable {@link SessionSnapshot} via
 * `subscribe()` — React consumes it through a single `useEffect`, and the
 * §27 screen machine maps it to `transcribing` / `transcriptionError` /
 * `scoreReady` / `audioReady`.
 */

import { SidecarClient, type SidecarClientOptions } from "./client";
import {
  ERR,
  SidecarError,
  type EngineCapabilities,
  type EngineInfo,
  type JobEventPayload,
  type JobStartResult,
} from "./protocol";
import type { SidecarPort } from "./port";
import {
  createJobView,
  markCancelling,
  markJobDead,
  reduceJobEvent,
  type JobView,
} from "./jobView";
import { extractReviewIssueCount } from "./review";

/** Real transcription job kind; the spike worker only knows
 *  `demoLongTask`, so the session falls back to it when `transcription`
 *  is not in `capabilities.jobKinds` — documented as the UI-002→UI-040
 *  bridge until the engine ships the real kind. */
export const TRANSCRIPTION_JOB_KIND = "transcription";
export const FALLBACK_JOB_KIND = "demoLongTask";

export type EngineStatus =
  /** No client yet (never started, or torn down). */
  | "offline"
  /** Spawn + handshake in flight. */
  | "starting"
  /** Handshake done — the engine can accept jobs. */
  | "ready"
  /** Worker exited unexpectedly (crash). Restart is an explicit action. */
  | "crashed"
  /** Watchdog: worker stopped answering mid-job. */
  | "unresponsive"
  /** Graceful shutdown completed. */
  | "closed";

/**
 * The failure classes the §20 error surfaces distinguish:
 * - `transcriptionFailed` — the job ended in a terminal `failed` event
 *   while the engine stayed alive → 再試行 is meaningful.
 * - `workerCrashed` — the process died mid-job → エンジンを再起動.
 * - `workerNotResponding` — watchdog probe timed out → エンジンを再起動.
 */
export type FailureKind =
  | "transcriptionFailed"
  | "workerCrashed"
  | "workerNotResponding";

export interface SessionFailure {
  kind: FailureKind;
  /** Machine-readable detail for the diagnostics surface — codes and
   *  engine messages stay OUT of normal UI copy (JAPANESE_UI_COPY §7). */
  detail: string;
  errorCode?: string;
}

export interface SessionSnapshot {
  engine: EngineStatus;
  engineInfo: EngineInfo | null;
  capabilities: EngineCapabilities | null;
  /** In-flight or just-ended job — null when idle. */
  job: JobView | null;
  /** Set on terminal failure; cleared on retry/restart/dismiss. */
  failure: SessionFailure | null;
  /**
   * The `completed` event's `result` payload — the score-data handoff
   * point. UI-030's adapter consumes this to build the canonical score
   * view; UI-040 only guarantees it is preserved verbatim and never
   * mutated by the progress layer.
   */
  lastResult: unknown;
  /** Count of open review issues in `lastResult` (0 when none). */
  reviewIssueCount: number;
  /** Recent supervision diagnostics (stderr + client notes). Ring buffer. */
  diagnostics: readonly string[];
}

type Listener = (snapshot: SessionSnapshot) => void;

export interface TranscriptionSessionOptions {
  portFactory: () => SidecarPort;
  clientOptions?: SidecarClientOptions;
  /** Max retained diagnostic lines. */
  diagnosticLogLimit?: number;
  /** Wall clock — injectable for tests. */
  now?: () => number;
}

const DEFAULT_DIAGNOSTIC_LIMIT = 80;

export class TranscriptionSession {
  private readonly portFactory: () => SidecarPort;
  private readonly clientOptions?: SidecarClientOptions;
  private readonly logLimit: number;
  private readonly now: () => number;
  private client: SidecarClient | null = null;
  private readonly listeners = new Set<Listener>();
  private snap: SessionSnapshot = {
    engine: "offline",
    engineInfo: null,
    capabilities: null,
    job: null,
    failure: null,
    lastResult: null,
    reviewIssueCount: 0,
    diagnostics: [],
  };
  private logLines: string[] = [];

  constructor(opts: TranscriptionSessionOptions) {
    this.portFactory = opts.portFactory;
    this.clientOptions = opts.clientOptions;
    this.logLimit = opts.diagnosticLogLimit ?? DEFAULT_DIAGNOSTIC_LIMIT;
    this.now = opts.now ?? (() => Date.now());
  }

  // ---- subscription -------------------------------------------------------

  getSnapshot(): SessionSnapshot {
    return this.snap;
  }

  subscribe(cb: Listener): () => void {
    this.listeners.add(cb);
    return () => this.listeners.delete(cb);
  }

  private update(patch: Partial<SessionSnapshot>): void {
    this.snap = { ...this.snap, ...patch };
    for (const cb of [...this.listeners]) cb(this.snap);
  }

  private log(line: string): void {
    this.logLines = [...this.logLines.slice(-(this.logLimit - 1)), line];
    this.update({ diagnostics: this.logLines });
  }

  // ---- engine lifecycle ------------------------------------------------------

  private buildClient(): SidecarClient {
    const client = new SidecarClient(this.portFactory(), this.clientOptions);
    client.onJobEvent((e) => this.onJobEvent(e));
    client.onStateChange((s) => this.onClientState(s));
    client.onDiagnostic((l) => this.log(l));
    return client;
  }

  /** Lazily spawn + handshake. Idempotent while `ready`. */
  private async ensureEngine(): Promise<void> {
    if (this.client && this.snap.engine === "ready") return;
    this.update({ engine: "starting" });
    const client = this.buildClient();
    this.client = client;
    try {
      const hs = await client.start();
      this.update({
        engine: "ready",
        engineInfo: hs.engineInfo,
        capabilities: hs.capabilities,
      });
    } catch (e) {
      // Spawn/handshake failure → the engine is down, the error surface
      // offers エンジンを再起動 (which builds a fresh port+client).
      this.update({
        engine: "crashed",
        failure: {
          kind: "workerNotResponding",
          detail: e instanceof Error ? e.message : String(e),
          errorCode: e instanceof SidecarError ? e.code : undefined,
        },
      });
      throw e;
    }
  }

  /**
   * エンジンを再起動 — the crash/unresponsive recovery action (§20).
   * Tears down the old client (best-effort shutdown, then kill) and runs
   * a fresh spawn + handshake. Never resubmits a job.
   */
  async restartEngine(): Promise<void> {
    const old = this.client;
    this.client = null;
    if (old) {
      old.shutdown(800).catch(() => undefined);
    }
    this.update({ engine: "starting", failure: null });
    const client = this.buildClient();
    this.client = client;
    try {
      const hs = await client.start();
      this.update({
        engine: "ready",
        engineInfo: hs.engineInfo,
        capabilities: hs.capabilities,
      });
    } catch (e) {
      this.update({
        engine: "crashed",
        failure: {
          kind: "workerNotResponding",
          detail: e instanceof Error ? e.message : String(e),
          errorCode: e instanceof SidecarError ? e.code : undefined,
        },
      });
      throw e;
    }
  }

  /** Graceful teardown for app shutdown — never throws. */
  async dispose(): Promise<void> {
    const client = this.client;
    this.client = null;
    if (client) await client.shutdown();
    this.update({ engine: "closed" });
  }

  // ---- jobs --------------------------------------------------------------------

  /** The jobKind to request: `transcription` when the engine advertises
   *  it, else the spike stand-in (documented bridge). */
  private transcriptionJobKind(): string {
    const kinds = this.snap.capabilities?.jobKinds;
    if (Array.isArray(kinds) && kinds.includes(TRANSCRIPTION_JOB_KIND)) {
      return TRANSCRIPTION_JOB_KIND;
    }
    return FALLBACK_JOB_KIND;
  }

  /**
   * `score.transcribe` → `job.start`. Explicit user action only — retry is
   * never silent (issue rule). Resolves once the job is accepted; progress
   * arrives as job.event frames afterwards.
   */
  async startTranscription(params: unknown = {}): Promise<void> {
    if (this.snap.job && !isSettled(this.snap.job)) {
      throw new SidecarError(ERR.JOB_ALREADY_RUNNING, "a job is already running");
    }
    this.update({ failure: null, lastResult: null, reviewIssueCount: 0 });
    await this.ensureEngine();
    const client = this.client;
    if (!client) {
      throw new SidecarError(ERR.ENGINE_UNAVAILABLE, "no engine client");
    }
    const kind = this.transcriptionJobKind();
    let accepted: JobStartResult;
    try {
      accepted = await client.startJob(kind, params);
    } catch (e) {
      // job.start itself was rejected (request timeout, INVALID_PARAMS, a
      // racing JOB_ALREADY_RUNNING). Surface an honest failure rather than
      // leaving the screen on a job that never existed — unless crash
      // supervision already set a stronger one (don't downgrade it).
      if (!this.snap.failure) {
        this.update({
          failure: {
            kind: "transcriptionFailed",
            detail: e instanceof Error ? e.message : String(e),
            errorCode: e instanceof SidecarError ? e.code : undefined,
          },
        });
      }
      throw e;
    }
    this.update({
      job: createJobView(accepted.jobId, kind, this.now()),
    });
  }

  /**
   * `job.cancel` — cooperative (PROTOCOL.md): the job ends in a terminal
   * `cancelled` event at the next checkpoint, so this resolves while the
   * job is still finishing. The UI shows the honest `cancelling` state
   * until the terminal event arrives.
   */
  async cancelTranscription(): Promise<void> {
    const job = this.snap.job;
    const client = this.client;
    if (!job || isSettled(job) || !client) return;
    if (job.phase === "cancelling") return;
    this.update({ job: markCancelling(job) });
    try {
      await client.cancelJob(job.jobId);
    } catch (e) {
      if (e instanceof SidecarError && e.code === ERR.JOB_NOT_FOUND) {
        // The job already reached a terminal event — fine, it wins.
        return;
      }
      // The cancel request itself failed — restore the honest running
      // state so the button does not lie about a pending cancel. Fold the
      // flag back onto the CURRENT view so progress/stage events that
      // arrived in the meantime are not lost.
      const current = this.snap.job;
      if (
        current &&
        current.jobId === job.jobId &&
        current.phase === "cancelling"
      ) {
        this.update({ job: { ...current, phase: "running" } });
      }
      throw e;
    }
  }

  // ---- event/state handling ----------------------------------------------------

  private onJobEvent(event: JobEventPayload): void {
    const job = this.snap.job;
    if (!job || event.jobId !== job.jobId) return;
    const next = reduceJobEvent(job, event);
    const patch: Partial<SessionSnapshot> = { job: next };
    if (next.phase === "completed") {
      patch.lastResult = next.result;
      patch.reviewIssueCount = extractReviewIssueCount(next.result);
    } else if (next.phase === "failed" && next.error) {
      // Engine stayed alive, the job failed → 再試行 surface.
      patch.failure = {
        kind: "transcriptionFailed",
        detail: `${next.error.code}: ${next.error.message}`,
        errorCode: next.error.code,
      };
    }
    this.update(patch);
  }

  private onClientState(state: string): void {
    switch (state) {
      case "ready":
        this.update({ engine: "ready" });
        break;
      case "starting":
        this.update({ engine: "starting" });
        break;
      case "closed":
        this.update({ engine: "closed" });
        break;
      case "crashed":
      case "unresponsive": {
        const engine = state as EngineStatus;
        const kind: FailureKind =
          state === "crashed" ? "workerCrashed" : "workerNotResponding";
        const code =
          state === "crashed" ? ERR.WORKER_CRASHED : ERR.WORKER_UNRESPONSIVE;
        const job = this.snap.job;
        const patch: Partial<SessionSnapshot> = { engine };
        // ADR-0002: an in-flight job gets NO terminal event from a dead
        // worker — the supervisor marks it failed explicitly.
        if (job && !isSettled(job)) {
          patch.job = markJobDead(job, {
            code,
            message:
              state === "crashed"
                ? "worker process exited while the job was in flight"
                : "worker did not answer the watchdog probe",
          });
          patch.failure = { kind, detail: code, errorCode: code };
        } else if (this.snap.engine === "ready" || this.snap.engine === "starting") {
          // Idle-engine death is reported through `engine` alone — the
          // status bar shows it; no modal error for a silent worker.
        }
        this.update(patch);
        break;
      }
    }
  }

  // ---- terminal bookkeeping ------------------------------------------------------

  /**
   * Clear the settled job record after the UI has consumed the terminal
   * state (completed → scoreReady handoff, cancelled → audioReady). The
   * `lastResult` handoff payload is preserved.
   */
  clearJob(): void {
    const job = this.snap.job;
    if (job && isSettled(job)) this.update({ job: null });
  }

  /** Dismiss the failure surface — the workspace returns to its prior
   *  valid state (audio stays loaded, a prior score is never destroyed). */
  clearFailure(): void {
    if (this.snap.failure) this.update({ failure: null });
  }

  /** Diagnostics text for the 診断情報 dialog (GUI_UX_SPEC §19 fields the
   *  session can honestly report; tool checks belong to UI-060). */
  buildDiagnostics(): string {
    const s = this.snap;
    const lines: string[] = [
      "HornScribe desktop — transcription session",
      `protocolVersion: 1`,
      `engine: ${s.engine}`,
      `engineInfo: ${s.engineInfo ? JSON.stringify(s.engineInfo) : "(none)"}`,
      `jobKinds: ${JSON.stringify(s.capabilities?.jobKinds ?? [])}`,
      `cooperativeCancel: ${String(s.capabilities?.cooperativeCancel ?? "?")}`,
      `cancellationFallback: ${String(s.capabilities?.cancellationFallback ?? "?")}`,
      `job: ${s.job ? `${s.job.jobId} ${s.job.phase}` : "(none)"}`,
      `failure: ${s.failure ? `${s.failure.kind} (${s.failure.detail})` : "(none)"}`,
      "— recent engine diagnostics —",
      ...s.diagnostics.slice(-30),
    ];
    return lines.join("\n");
  }
}

function isSettled(job: JobView): boolean {
  return (
    job.phase === "completed" ||
    job.phase === "cancelled" ||
    job.phase === "failed"
  );
}

/**
 * HornScribe app shell layout + token consumers.
 * Colors come only from --hs-* semantic tokens (tokens.css).
 */

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--hs-font-family);
  font-size: var(--hs-font-size-body);
  color: var(--hs-text-primary);
  background: var(--hs-surface-app);
  overflow: hidden;
}

/* UI-009 latent bug, fixed for the real shell (UI-011): FluentProvider
   renders a wrapper div between #root and the shell; without a definite
   height the `height:100%` grid below collapsed to content height. */
.hs-provider {
  height: 100%;
}

/* ---- Visible keyboard focus (DESIGN_SYSTEM §16) ----
   2px+, distinct from adjacent surface; Fluent v9 components draw their own
   compatible focus ring, this guarantees the same contract for every other
   focusable region (waveform, score surface, segmented control, links). */
:focus-visible {
  outline: var(--hs-focus-width) solid var(--hs-focus);
  outline-offset: var(--hs-focus-offset);
  border-radius: var(--hs-radius-input);
}
/* Never remove the outline without a replacement. */
:focus:not(:focus-visible) {
  outline: none;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ============================ App shell ============================ */
/* GUI_UX_SPEC §2 information architecture:
   title bar → command bar → waveform → score workspace → transport → status */
.hs-shell {
  display: grid;
  grid-template-rows: auto auto auto minmax(0, 1fr) auto auto;
  grid-template-areas:
    "titlebar"
    "commandbar"
    "waveform"
    "main"
    "transport"
    "statusbar";
  height: 100%;
  min-width: 0;
  /* §21: <1100px is unsupported — the native window minimum (1100×640 in
     tauri.conf.json) stops resizing first; this floor mirrors it so a
     browser dev viewport can never compress the layout below spec. With
     body overflow:hidden the excess clips instead of scrolling — there is
     deliberately no app-level horizontal scroll. */
  min-width: 1100px;
  min-height: 640px;
  background: var(--hs-surface-app);
  color: var(--hs-text-primary);
}

/* ---- Title bar area (in-app; native window chrome is kept) ---- */
.hs-titlebar {
  grid-area: titlebar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 32px;
  padding: 0 var(--hs-space-ms);
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-secondary);
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  user-select: none;
}
.hs-titlebar__app {
  font-weight: 600;
  color: var(--hs-text-primary);
}
.hs-titlebar__doc {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---- Command bar (DESIGN_SYSTEM §10: ~44px, never scrolls) ---- */
.hs-commandbar {
  grid-area: commandbar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 44px;
  padding: 0 var(--hs-space-ms);
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  overflow: hidden;
  white-space: nowrap;
}
/* Buttons never shrink/clip — below 1600px secondary labels hide instead
   (§21 icon化), below 1200px 設定 moves to the overflow menu. */
.hs-commandbar .fui-ToolbarButton,
.hs-commandbar .fui-Button {
  flex-shrink: 0;
}
/* 1200–1599px: secondary commands render icon-only; their Tooltip carries
   the full Japanese label (§24). Labels are hidden, never ellipsized. */
@media (max-width: 1599px) {
  .hs-commandbar__label {
    display: none;
  }
}
.hs-commandbar__spacer {
  flex: 1 1 auto;
  min-width: var(--hs-space-sm);
}

/* ---- Segmented control (DESIGN_SYSTEM §11: text labels, never icon-only) ---- */
.hs-segmented {
  display: inline-flex;
  flex: 0 0 auto;
  border: 1px solid var(--hs-border-strong);
  border-radius: var(--hs-radius-input);
  overflow: hidden;
  background: var(--hs-surface-elevated);
}
.hs-segmented__item {
  appearance: none;
  border: none;
  background: transparent;
  color: var(--hs-text-secondary);
  font-family: var(--hs-font-family);
  font-size: var(--hs-font-size-compact);
  line-height: 1;
  padding: 8px 12px;
  cursor: pointer;
  white-space: nowrap;
}
.hs-segmented__item + .hs-segmented__item {
  border-left: 1px solid var(--hs-border-subtle);
}
.hs-segmented__item:hover {
  background: var(--hs-control-hover);
}
/* selected state = fill + weight + border cues combined (§11);
   on-accent text color keeps ≥4.5:1 in both themes (dark accent is light,
   so the foreground flips to dark ink via --hs-accent-foreground). */
.hs-segmented__item[aria-checked="true"] {
  background: var(--hs-accent);
  color: var(--hs-accent-foreground);
  font-weight: var(--hs-font-weight-emphasis);
  box-shadow: inset 0 0 0 1px var(--hs-accent-pressed);
}
.hs-segmented__item:focus-visible {
  outline-offset: -2px;
}

/* ---- Waveform region (GUI_UX_SPEC §8: 96–120px standard) ----
   Height is inline (user-resizable via the bottom-edge separator);
   min/max here are the CSS backstop, JS clamps are authoritative. */
.hs-waveform {
  grid-area: waveform;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 64px;
  max-height: 35vh;
  background: var(--hs-surface-panel);
  border-bottom: 1px solid var(--hs-border-subtle);
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-compact);
}
.hs-waveform__resizer {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -4px;
  height: 8px;
  cursor: row-resize;
  touch-action: none;
  z-index: 6;
}

/* Shared separator affordance: quiet until hover/focus (§8 elevation —
   workspace stays flat, so the grip uses a translucent accent wash). */
.hs-waveform__resizer:hover,
.hs-waveform__resizer:focus-visible,
.hs-properties__resizer:hover,
.hs-properties__resizer:focus-visible {
  background: color-mix(in srgb, var(--hs-accent) 30%, transparent);
}

/* ---- Score workspace + properties ---- */
.hs-main {
  grid-area: main;
  position: relative; /* anchor for the overlay properties drawer */
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  min-height: 0;
  min-width: 0;
}

.hs-score {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--hs-space-md);
  min-width: 0;
  min-height: 0;
  padding: var(--hs-space-lg);
  background: var(--hs-surface-score);
  color: var(--hs-text-primary);
  /* Score paper keeps a hairline radius, not decorative rounding (§7). */
  border-radius: var(--hs-radius-score-paper);
  overflow: auto;
}
.hs-score--dragover {
  outline: 2px dashed var(--hs-accent);
  outline-offset: -8px;
}
.hs-score__empty-title {
  margin: 0;
  font-size: var(--hs-font-size-title);
  font-weight: 400;
  color: var(--hs-text-primary);
}
/* Score-ready placeholder paper: bounded page shape inside the score
   surface until UI-003 renders real notation. */
.hs-score-paper {
  display: flex;
  align-items: center;
  justify-content: center;
  align-self: stretch;
  flex: 1 1 auto;
  min-height: 0;
  margin: var(--hs-space-xs);
  border: 1px solid var(--hs-score-paper-border);
  border-radius: var(--hs-radius-score-paper);
  background: var(--hs-surface-score);
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-compact);
}

/* Properties inspector (§6, §21): docked at ≥1200px with an inline width
   inside the breakpoint clamp; <1200px it becomes a non-modal overlay
   drawer so the score keeps the workspace. */
.hs-properties {
  position: relative;
  display: flex;
  flex-direction: row;
  min-width: 0;
  min-height: 0;
  background: var(--hs-surface-panel);
  border-left: 1px solid var(--hs-border-subtle);
  color: var(--hs-text-secondary);
}
.hs-properties--overlay {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  z-index: 8;
  background: var(--hs-surface-elevated);
  box-shadow: var(--hs-elevation-sheet);
}
.hs-properties__frame {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
}
.hs-properties__header {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  min-height: 40px;
  padding: var(--hs-space-xs) var(--hs-space-sm) var(--hs-space-xs)
    var(--hs-space-md);
  border-bottom: 1px solid var(--hs-border-subtle);
}
.hs-properties__title {
  flex: 1 1 auto;
  margin: 0;
  font-size: var(--hs-font-size-subtitle);
  font-weight: 600;
  color: var(--hs-text-primary);
}
.hs-properties__body {
  flex: 1 1 auto;
  min-height: 0;
  padding: var(--hs-space-md);
  overflow: auto;
}
.hs-properties__placeholder {
  margin: 0;
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-muted);
}
.hs-properties__resizer {
  position: absolute;
  top: 0;
  bottom: 0;
  left: -5px;
  width: 9px;
  cursor: col-resize;
  touch-action: none;
  z-index: 6;
}
/* Panel open/close motion (§25 panel tier; reduced-motion collapses it). */
@keyframes hs-panel-in {
  from {
    transform: translateX(12px);
    opacity: 0;
  }
  to {
    transform: none;
    opacity: 1;
  }
}
.hs-properties {
  animation: hs-panel-in var(--hs-motion-panel) var(--hs-ease-decelerate);
}

/* ---- Empty state (GUI_UX_SPEC §3, §19: compact, clear CTA) ---- */
.hs-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--hs-space-sm);
  text-align: center;
  max-width: 46em;
}
.hs-empty__title {
  margin: 0;
  font-size: var(--hs-font-size-display);
  font-weight: 400;
}
.hs-empty__or {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-caption);
}
.hs-empty__formats {
  margin: var(--hs-space-xs) 0 0;
  color: var(--hs-text-secondary);
  font-size: var(--hs-font-size-compact);
}
.hs-empty__privacy {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-caption);
}

/* ---- Transport (GUI_UX_SPEC §9) ---- */
.hs-transport {
  grid-area: transport;
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  height: 52px;
  padding: 0 var(--hs-space-ms);
  background: var(--hs-surface-panel);
  border-top: 1px solid var(--hs-border-subtle);
}
.hs-transport__time {
  font-variant-numeric: tabular-nums; /* §5: timecode uses tabular numerals */
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-secondary);
  margin-left: var(--hs-space-sm);
  white-space: nowrap;
}
.hs-transport__spacer {
  flex: 1 1 auto;
}

/* ---- Status bar ---- */
.hs-statusbar {
  grid-area: statusbar;
  display: flex;
  align-items: center;
  gap: var(--hs-space-md);
  height: 26px;
  padding: 0 var(--hs-space-ms);
  font-size: var(--hs-font-size-caption);
  color: var(--hs-text-muted);
  background: var(--hs-surface-panel);
  border-top: 1px solid var(--hs-border-subtle);
  user-select: none;
}
.hs-statusbar__message {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hs-statusbar__spacer {
  flex: 1 1 auto;
}

/* ====================== Primitives (components/primitives) ======================
   Only --hs-* semantic tokens; raw values live exclusively in tokens.css. */

/* ---- HsButton (§9): danger re-tints the primary fill to palette red ----
   Double-class selectors keep precedence over Fluent's atomic classes. */
.hs-button.hs-button--danger:not(:disabled) {
  background-color: var(--hs-danger);
  color: var(--hs-danger-foreground);
  border-color: transparent;
}
.hs-button.hs-button--danger:not(:disabled):hover {
  background-color: var(--hs-danger-hover);
}
.hs-button.hs-button--danger:not(:disabled):active {
  background-color: var(--hs-danger-pressed);
}
/* State changes use the fast motion tier (§18). */
.hs-button {
  transition-duration: var(--hs-motion-fast);
  transition-timing-function: var(--hs-ease-standard);
}

/* ---- Segmented control additions (§11, §17) ---- */
.hs-segmented__item:disabled {
  color: var(--hs-text-disabled);
  cursor: not-allowed;
}
.hs-segmented__item:disabled:hover {
  background: transparent;
}
.hs-segmented__item {
  transition: background-color var(--hs-motion-fast) var(--hs-ease-standard);
}

/* ---- StatusBadge / ReviewBadge (§15): tint + glyph + (review) dotted cue ---- */
.hs-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--hs-space-xs);
  padding: 1px var(--hs-space-sm);
  border-radius: var(--hs-radius-input);
  border: 1px solid transparent;
  font-size: var(--hs-font-size-caption);
  line-height: var(--hs-line-height-caption);
  font-weight: var(--hs-font-weight-emphasis);
  white-space: nowrap;
  user-select: none;
}
.hs-badge__icon {
  display: inline-flex;
  font-size: 14px;
}
.hs-badge--neutral {
  color: var(--hs-text-secondary);
  background: var(--hs-status-neutral-subtle);
  border-color: color-mix(in srgb, currentColor 25%, transparent);
}
.hs-badge--info {
  color: var(--hs-status-info);
  background: var(--hs-status-info-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
.hs-badge--success {
  color: var(--hs-status-success);
  background: var(--hs-status-success-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
.hs-badge--warning {
  color: var(--hs-status-warning);
  background: var(--hs-status-warning-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
.hs-badge--error {
  color: var(--hs-status-error);
  background: var(--hs-status-error-subtle);
  border-color: color-mix(in srgb, currentColor 35%, transparent);
}
/* §15: the 要確認 marker adds a dotted underline — review is never red. */
.hs-badge--needs-review .hs-badge__label {
  border-bottom: 2px dotted var(--hs-review-marker);
}

/* ---- HsPanel (§8): flat separation by border; elevated for floats ---- */
.hs-panel {
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: var(--hs-surface-panel);
  border: 1px solid var(--hs-border-subtle);
  border-radius: var(--hs-radius-panel);
  color: var(--hs-text-primary);
}
.hs-panel--elevated {
  background: var(--hs-surface-elevated);
  box-shadow: var(--hs-elevation-popover);
}
.hs-panel__header {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
  padding: var(--hs-space-sm) var(--hs-space-ms);
  border-bottom: 1px solid var(--hs-border-subtle);
  min-height: 40px;
}
.hs-panel__title {
  margin: 0;
  font-size: var(--hs-font-size-subtitle);
  line-height: var(--hs-line-height-subtitle);
  font-weight: var(--hs-font-weight-title);
}
.hs-panel__header-spacer {
  flex: 1 1 auto;
}
.hs-panel__body {
  padding: var(--hs-space-md);
  min-width: 0;
}
.hs-panel__body--flush {
  padding: 0;
}

/* ---- HsSlider: track + tabular readout (§5) ---- */
.hs-slider {
  display: flex;
  align-items: center;
  gap: var(--hs-space-sm);
}
.hs-slider .fui-Slider {
  flex: 1 1 auto;
}
.hs-slider__value {
  flex: 0 0 auto;
  min-width: 3.5em;
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-size: var(--hs-font-size-compact);
  line-height: var(--hs-line-height-compact);
  color: var(--hs-text-secondary);
}

/* ---- Settings (auxiliary screen, §18): replaces the workspace rows ---- */
.hs-settings-wrap {
  grid-row: commandbar / transport; /* spans commandbar…main rows */
  display: flex;
  min-height: 0;
  min-width: 0;
}
.hs-settings {
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  padding: var(--hs-space-lg);
  background: var(--hs-surface-app);
  overflow: auto;
}
.hs-settings__title {
  margin: 0 0 var(--hs-space-md);
  font-size: var(--hs-font-size-title);
  font-weight: 600;
}
/* Section chrome (border / radius / padding) comes from the HsPanel
   primitive; this class only constrains width and rhythm. */
.hs-settings__section {
  margin: 0 0 var(--hs-space-lg);
  max-width: 560px;
}
.hs-settings__note {
  margin: 0;
  color: var(--hs-text-muted);
  font-size: var(--hs-font-size-compact);
}

/* ============================ UI-040: 採譜中 ============================
   Transcribing body (GUI_UX_SPEC §5) — lives inside the score region;
   not a modal, so the rest of the shell stays usable. */

/* Screen-reader-only text (aria-live announcements, a11y §24). */
.hs-visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
